INSERT INTO anomaly_records (id, centre_id, category, description, severity, anomaly_date, evidence, review_status, reviewed_by, review_notes) VALUES
('2995bb3d-624f-4f00-9d2a-566a641efd9b', 'cbdd1743-8320-54b5-b662-e9be8df49a90', 'attendance_drop', 'Sudden 38% attendance drop observed in Batch BAT-03-01 on Feb 12th compared to moving average', 'high', '2024-02-12', '{"batch": "BAT-03-01", "normal_rate": 88.5, "day_rate": 50.5, "variance": -38.0}'::jsonb, 'open', '4221d673-7425-5a1a-ac26-1feaa3689d54', 'Investigating potential local festival or unreported transport interruption.'),
('f02bbcc8-2419-4abd-a7a5-ee41d25431a3', 'eb5183de-2eb9-5380-88b9-5814097d4ba7', 'identical_patterns', 'Repeated identical attendance pattern: 18 students marked present at exact identical timestamps over 5 consecutive days', 'critical', '2024-02-14', '{"pattern_length_days": 5, "matching_students": 18, "similarity_index": 1.0}'::jsonb, 'under_review', '4221d673-7425-5a1a-ac26-1feaa3689d54', 'Evidence indicates possible bulk attendance copy-paste without physical verification.'),
('d5bed8cb-75fe-4dbe-8481-62de1d88440b', '27293bab-4201-5fae-b4ec-1487250227a0', 'trainer_discrepancy', 'Trainer Deepak Gowda marked present for 4h session but zero student attendance logged for BAT-02-02', 'medium', '2024-02-10', '{"trainer_id": "TRN-004", "session_hours": 4.0, "student_logs_count": 0}'::jsonb, 'resolved', '4221d673-7425-5a1a-ac26-1feaa3689d54', 'Trainer conducted makeup lecture; attendance sheet uploaded under delayed sync.'),
('5301b996-6768-4bfc-8236-b01299851080', '1491a53a-f6eb-5967-bfdb-5ed7d3e759e2', 'duplicate_records', '12 student attendance records submitted with identical biometric hash on 2024-01-22', 'low', '2024-01-22', '{"duplicate_count": 12}'::jsonb, 'false_positive', '4221d673-7425-5a1a-ac26-1feaa3689d54', 'Scanner software glitch re-sent duplicate batch packet; cleared.');
